const SAST = 2;
const WINDOW_DAYS = Number(input.window_days || 7);
const WORKING_DAYS = [1, 2, 3, 4, 5, 6];
const CUTOFF = String(input.same_day_cutoff || "07:00");
const HOLIDAYS = String(input.holidays || "").split(",").map(s => s.trim()).filter(Boolean);
const DAY = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
const MON = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
const MS = 86400000;
const now = input.now_iso ? new Date(input.now_iso) : new Date();
const sast = new Date(now.getTime() + SAST * 3600000);
const today = Date.UTC(sast.getUTCFullYear(), sast.getUTCMonth(), sast.getUTCDate());
const nowHHMM = String(sast.getUTCHours()).padStart(2, "0") + ":" + String(sast.getUTCMinutes()).padStart(2, "0");
const firstOffset = nowHHMM < CUTOFF ? 0 : 1;
const rows = [];
for (let off = firstOffset; off <= WINDOW_DAYS && rows.length < 9; off++) {
const t = today + off * MS, d = new Date(t), iso = d.toISOString().slice(0, 10);
if (!WORKING_DAYS.includes(d.getUTCDay())) continue;
const hol = HOLIDAYS.includes(iso);
rows.push({
id: "day_" + iso,
title: DAY[d.getUTCDay()] + " " + d.getUTCDate() + " " + MON[d.getUTCMonth()],
description: (off === 0 ? "Today" : off === 1 ? "Tomorrow" : "In " + off + " days") + (hol ? " · public holiday +R60" : "")
});
}
rows.push({ id: "day_later", title: "Later date", description: "More than a week away? Message Nita" });
return { sections_json: JSON.stringify([{ title: "Available days", rows: rows }]), day_count: rows.length - 1 };

const DURATION_HOURS = { svc_basic: 2, svc_deep: 3.5, svc_moveout: 4 };
const SERVICE_LABEL = { svc_basic: "Basic Clean", svc_deep: "Deep Clean", svc_moveout: "Move Out / Move In Clean" };
const SLOTS = { slot_0800: "08:00", slot_1200: "12:00", slot_1500: "15:00" };
const MIN_LEAD_MIN = 60;
const DAY = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
const MON = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
const pad = n => String(n).padStart(2, "0");
const bad = (code, text) => ({ ok: false, error: code, error_text_json: JSON.stringify(text) });
const dayIso = String(input.day_id || "").replace(/^day_/, "");
const service = String(input.service_id || "");
const slot = SLOTS[String(input.slot_id || "")];
if (!/^\d{4}-\d{2}-\d{2}$/.test(dayIso) || !DURATION_HOURS[service] || !slot)
return bad("bad_input", "Sorry, that option has expired. Send *hi* to start a new booking.");
const startIso = dayIso + "T" + slot + ":00+02:00";
const now = input.now_iso ? new Date(input.now_iso) : new Date();
if (Date.parse(startIso) < now.getTime() + MIN_LEAD_MIN * 60000)
return bad("too_soon", "Sorry, that time has already passed or is too soon. Send *hi* to pick another day or time.");
const [h, m] = slot.split(":").map(Number);
const endMin = h * 60 + m + Math.round(DURATION_HOURS[service] * 60);
const endIso = dayIso + "T" + pad(Math.floor(endMin / 60)) + ":" + pad(endMin % 60) + ":00+02:00";
const d = new Date(dayIso + "T12:00:00Z");
const dayLabel = DAY[d.getUTCDay()] + " " + d.getUTCDate() + " " + MON[d.getUTCMonth()];
const hrs = DURATION_HOURS[service];
return {
ok: true, error: "", error_text_json: "\"\"",
service_label: SERVICE_LABEL[service], duration_hours: hrs,
start_iso: startIso, end_iso: endIso,
day_label: dayLabel, time_label: slot,
when_label: dayLabel + ", " + slot + " (about " + hrs + " hrs)"
};

const CAPACITY = 2;
let raw = input.events_json;
if (typeof raw === "string") {
try { raw = JSON.parse(raw || "{}"); } catch (e) { return { ok: false, error: "events_not_json", slot_full: true }; }
}
const items = Array.isArray(raw) ? raw : ((raw && (raw.items || (raw.body && raw.body.items))) || []);
const newStart = Date.parse(input.start_iso);
const newEnd = Date.parse(input.end_iso);
if (isNaN(newStart) || isNaN(newEnd)) return { ok: false, error: "bad_times", slot_full: true };
const overlaps = items
.filter(e => e && e.status !== "cancelled" && e.start && e.start.dateTime && e.end && e.end.dateTime)
.map(e => [Math.max(Date.parse(e.start.dateTime), newStart), Math.min(Date.parse(e.end.dateTime), newEnd)])
.filter(([s, e]) => e > s);
const points = [];
overlaps.forEach(([s, e]) => { points.push([s, 1]); points.push([e, -1]); });
points.sort((a, b) => a[0] - b[0] || a[1] - b[1]); // an end and a start at the same minute don't clash
let running = 0, peak = 0;
points.forEach(([, step]) => { running += step; if (running > peak) peak = running; });
return {
ok: true,
error: "",
slot_full: peak >= CAPACITY,
peak_busy: peak,
places_left: Math.max(0, CAPACITY - peak),
overlapping_events: overlaps.length
};

